class Broker:
    """
    Pub/sub message backbone.

    Redis-backed when a ``redis_client`` is supplied (or ``REDIS_URL`` is set);
    otherwise backed by a shared in-memory hub. Both modes expose the same
    interface so servers behave identically either way.
    """

    def __init__(
        self,
        redis_client=None,
        hub: _MemoryHub | None = None,
    ) -> None:
        self.redis_client = redis_client
        self._hub = hub or _MemoryHub()
        self._pubsub = None
        self._queue: asyncio.Queue | None = None
        self._subscribed: set[str] = set()
        self._lock = threading.RLock()
        self._connected = False

    @property
    def redis_enabled(self) -> bool:
        return self.redis_client is not None

    async def connect(self) -> None:
        """Prepare the broker for use, degrading gracefully to in-memory."""
        if self._connected:
            return
        if self.redis_client is not None:
            try:
                await self.redis_client.ping()
            except Exception:
                self.redis_client = None
        self._connected = True
        if self.redis_client is not None:
            self._pubsub = self.redis_client.pubsub()
        else:
            self._queue = asyncio.Queue()

    async def subscribe(self, channel: str) -> None:
        await self.connect()
        with self._lock:
            if channel in self._subscribed:
                return
            self._subscribed.add(channel)
        if self.redis_client is not None:
            await self._pubsub.subscribe(channel)
        else:
            self._hub.subscribe(channel, self)

    async def unsubscribe(self, channel: str) -> None:
        await self.connect()
        with self._lock:
            if channel not in self._subscribed:
                return
            self._subscribed.discard(channel)
        if self.redis_client is not None:
            await self._pubsub.unsubscribe(channel)
        else:
            self._hub.unsubscribe(channel, self)

    def channels_subscribed(self) -> set[str]:
        with self._lock:
            return set(self._subscribed)

    def _enqueue(self, channel: str, data: str) -> None:
        if self._queue is not None:
            self._queue.put_nowait((channel, data))

    async def publish(self, channel: str, payload: dict) -> None:
        """Publish a message dict to a channel."""
        await self.connect()
        data = json.dumps(payload)
        if self.redis_client is not None:
            await self.redis_client.publish(channel, data)
        else:
            self._hub.publish(channel, data)

    async def next_message(self):
        """
        Return the next ``(channel, data)`` delivered to this broker, or ``None``
        when nothing is pending. Both modes poll so cancellation during event
        loop shutdown is clean.
        """
        await self.connect()
        if self.redis_client is not None:
            msg = await self._pubsub.get_message(ignore_subscribe_messages=True)
            if msg is None:
                await asyncio.sleep(0.01)
                return None
            channel = _decode(msg.get("channel"))
            data = _decode(msg.get("data"))
            if channel is None or data is None:
                return None
            return channel, data
        try:
            channel, data = self._queue.get_nowait()
        except asyncio.QueueEmpty:
            await asyncio.sleep(0.01)
            return None
        return channel, data


def _make_default_broker() -> Broker:
    """Build the process-wide default broker from the environment."""
    if not REDIS_URL:
        return Broker()
    try:
        import redis.asyncio as aioredis
    except ImportError:
        return Broker()
    try:
        client = aioredis.from_url(REDIS_URL)
    except Exception:
        return Broker()
    return Broker(redis_client=client)


